"""Invitation par courriel (la personne choisit son mot de passe) + guide « Mettre l'app sur ton téléphone » — version équipe, copie locale de Supabase."""
from team_seed import *
from playwright.sync_api import sync_playwright
QRJS = open(os.path.join(SC, 'qrlib/node_modules/qrcode-generator/qrcode.js'), encoding='utf8').read()
ANDROID = 'Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0 Mobile Safari/537.36'
def ghl_log(): return http('GET', 'http://127.0.0.1:9200/__log') or []
def mk(b, phone=False, ua=None, standalone=False):
    c = ctx(b, phone=phone)
    if ua: c = b.new_context(viewport={'width': 412, 'height': 900}, timezone_id='America/Toronto', locale='fr-CA', has_touch=True, user_agent=ua, is_mobile=True)
    c.route('https://cdn.jsdelivr.net/npm/qrcode-generator@1.4.4/qrcode.js', lambda r: r.fulfill(status=200, content_type='application/javascript', body=QRJS, headers={'Access-Control-Allow-Origin': '*'}))
    c.route('https://tile.openstreetmap.org/**', lambda r: r.fulfill(status=200, content_type='image/png', body=b''))
    c.route('https://fonts.**', lambda r: r.abort())
    if standalone: c.add_init_script("Object.defineProperty(navigator, 'standalone', {get: () => true})")
    return c
def invite_link():
    for e in reversed(ghl_log()):
        if e['path'] == '/conversations/messages' and e['body'].get('type') == 'Email':
            m = re.search(r'(http://127\.0\.0\.1:8088/#invite=[A-Za-z0-9_-]+)', e['body'].get('message', ''))
            if m: return m.group(1), e['body']
    return None, None
otok, pw = seed()
with sync_playwright() as pl:
    b = pl.chromium.launch()
    # ---------- 1. owner invites someone by email (texts/emails connected) ----------
    oc = mk(b); op = page(oc, 'owner'); op.set_viewport_size({'width': 1280, 'height': 900}); login(op, 'hassan@garage.test', pw['hassan'])
    op.evaluate("location.hash = 'equipe'"); op.wait_for_selector('#eq-new', timeout=10000)
    check('Équipe et accès: « Inviter une personne » with « Envoyer l\'invitation »', 'Inviter une personne' in txt(op, '#eq-new h3') and op.is_visible('#eq-new [data-act="eq-invite"]'))
    check('temporary password is now the other way (folded)', op.locator('#eq-new details [data-act="eq-add"]').count() == 1 and not op.is_visible('#eq-new [data-act="eq-add"]'))
    op.fill('#nw-name', 'Karim Test'); op.fill('#nw-email', 'karim@garage.test'); op.select_option('#nw-role', 'bureau')
    op.click('[data-act="eq-invite"]'); op.wait_for_selector('#eq-invited', timeout=15000)
    check('card « Invitation envoyée à Karim Test »', 'Invitation envoyée à Karim Test' in txt(op, '#eq-invited h3'), txt(op, '#eq-invited'))
    link, mail = invite_link()
    check('the email went out through GoHighLevel (contact by email, type Email)', link is not None and any(e['path'] == '/contacts/upsert' and e['body'].get('email') == 'karim@garage.test' for e in ghl_log()), [e['path'] for e in ghl_log()])
    check('email: subject, « Activer mon compte » button with the link, how to put the app on the phone',
          mail and mail['subject'] == 'Ton accès au carnet de Garage NextLine' and 'Activer mon compte' in mail['html'] and link in mail['html'] and 'Sur l\'écran d\'accueil' in mail['message'] and 'Installer l\'application' in mail['message'], (mail or {}).get('subject'))
    row = op.locator('.eqp', has_text='karim@garage.test')
    check('list: « Invitation envoyée … pas encore activé » + « Renvoyer l\'invitation »', 'Invitation envoyée' in row.inner_text() and 'pas encore activé' in row.inner_text() and row.locator('[data-act="eq-reinvite"]').count() == 1)
    uid = psql("select id from auth.users where email='karim@garage.test'")
    check('invites table keeps only a fingerprint of the link', psql("select count(*) from public.invites where user_id='%s' and used_at is null" % uid) == '1' and link.split('#invite=')[1] not in psql("select token_hash from public.invites where user_id='%s'" % uid))
    check('nobody can read invitations through the API', '_status' in (http('GET', API + '/rest/v1/invites?select=*', token=otok) or {'_status': 0}))
    # ---------- 2. the person opens the link on a phone ----------
    kc = mk(b, phone=True); kp = page(kc, 'karim'); kp.goto(link); kp.wait_for_selector('#gate #g-pw', timeout=15000)
    check('link: « Bonjour Karim ! », his email, no password to type twice by mistake', 'Bonjour Karim' in txt(kp, '#g-title') and kp.input_value('#g-email') == 'karim@garage.test' and kp.get_attribute('#g-email', 'readonly') is not None)
    check('the secret is removed from the address bar', '#invite=' not in kp.url, kp.url)
    kp.fill('#g-pw', 'Court1'); kp.fill('#g-pw2', 'Court1'); kp.click('#g-go'); kp.wait_for_timeout(200)
    check('too short → plain message', '8 caractères' in txt(kp, '#g-msg'))
    kp.fill('#g-pw', 'Karim-Garage-26'); kp.fill('#g-pw2', 'Karim-Garage-27'); kp.click('#g-go'); kp.wait_for_timeout(200)
    check('typed differently → plain message', 'pas pareils' in txt(kp, '#g-msg'))
    kp.fill('#g-pw2', 'Karim-Garage-26'); kp.click('#g-go'); kp.wait_for_selector('#gate', state='detached', timeout=20000); kp.wait_for_timeout(1500)
    check('« Activer mon compte » → signed in to the garage', kp.locator('#tabbar').count() == 1 and kp.evaluate("!!window.__garageApi && window.__garageApi.S.loaded"))
    check('right after: how to put the app on the phone opens by itself (iPhone first)', kp.locator('#sheet:not([hidden]) .inst').count() == 1 and kp.locator('.inst .inst-b').first.get_attribute('data-p') == 'ios', kp.locator('.inst .inst-b').count())
    check('steps are concrete: Safari, Partager, « Sur l\'écran d\'accueil », « Ajouter »', all(w in txt(kp, '.inst') for w in ['Safari', 'Partager', 'Sur l\'écran d\'accueil', 'Ajouter']))
    kp.click('[data-act="app-done"]'); kp.wait_for_timeout(600)
    check('« C\'est fait » is remembered for that person', bool((doc('data/users/%s/app' % uid) or {}).get('installedAt')), doc('data/users/%s/app' % uid))
    check('invite used once (marked used)', psql("select count(*) from public.invites where user_id='%s' and used_at is not null" % uid) == '1')
    kc.close()
    k2 = mk(b, phone=True); k2p = page(k2, 'karim2'); k2p.goto(link); k2p.wait_for_selector('#gate .g-msg', timeout=15000)
    check('the same link a second time: « plus valide »', 'plus valide' in txt(k2p, '#gate .g-msg'), txt(k2p, '#gate'))
    k2p.click('#g-go'); k2p.wait_for_selector('#g-email', timeout=5000)
    k2p.fill('#g-email', 'karim@garage.test'); k2p.fill('#g-pw', 'Karim-Garage-26'); k2p.click('#g-go'); k2p.wait_for_selector('#gate', state='detached', timeout=20000)
    check('then he signs in normally with his own password', k2p.locator('#tabbar').count() == 1)
    k2.close()
    op.reload(); op.wait_for_timeout(800); op.evaluate("location.hash = 'equipe'"); op.wait_for_selector('.eqp', timeout=10000); op.wait_for_timeout(500)
    row = op.locator('.eqp', has_text='karim@garage.test')
    check('owner list: Karim activated (last sign-in, no « Renvoyer »)', 'dernière connexion' in row.inner_text() and row.locator('[data-act="eq-reinvite"]').count() == 0, row.inner_text())
    # ---------- 3. without automatic emails: the owner sends it himself; resend ----------
    fn(otok, 'members', {'action': 'secrets-set', 'ghlToken': '', 'ghlLocation': ''})
    op.reload(); op.wait_for_timeout(800); op.evaluate("location.hash = 'equipe'"); op.wait_for_selector('#eq-new', timeout=10000)
    op.fill('#nw-name', 'Léa Test'); op.fill('#nw-email', 'lea@garage.test'); op.select_option('#nw-role', 'tresorier')
    op.click('[data-act="eq-invite"]'); op.wait_for_selector('#eq-invited', timeout=15000)
    href = op.get_attribute('#inv-mail', 'href') or ''
    check('no automatic email: « Invitation prête » + « Envoyer par courriel » already written', 'Invitation prête pour Léa Test' in txt(op, '#eq-invited h3') and href.startswith('mailto:lea@garage.test?subject=') and '%23invite%3D' in href and op.locator('#eq-invited [data-act="eq-copylink"]').count() == 1, href[:120])
    lea = psql("select id from auth.users where email='lea@garage.test'")
    old = fn(otok, 'members', {'action': 'invite-resend', 'user_id': lea, 'base': BASE})
    new = fn(otok, 'members', {'action': 'invite-resend', 'user_id': lea, 'base': BASE})
    t_old, t_new = old['link'].split('#invite=')[1], new['link'].split('#invite=')[1]
    check('« Renvoyer » makes a new link and the older one stops working', fn(None, 'members', {'action': 'invite-info', 'token': t_old}).get('error') == 'bad_invite' and fn(None, 'members', {'action': 'invite-info', 'token': t_new}).get('email') == 'lea@garage.test')
    check('invite-info tells only the name, email, role and garage', set(fn(None, 'members', {'action': 'invite-info', 'token': t_new}).keys()) == {'ok', 'name', 'role', 'email', 'garage'})
    psql("update public.invites set expires_at = now() - interval '1 minute' where user_id='%s'" % lea)
    check('after 7 days the link no longer works', fn(None, 'members', {'action': 'invite-accept', 'token': t_new, 'password': 'Lea-Garage-26'}).get('error') == 'bad_invite')
    check('garbage link refused', fn(None, 'members', {'action': 'invite-info', 'token': 'x' * 30}).get('error') == 'bad_invite' and fn(None, 'members', {'action': 'invite-accept', 'token': 'abc', 'password': 'Lea-Garage-26'}).get('error') == 'bad_invite')
    dup = fn(otok, 'members', {'action': 'invite', 'name': 'Karim Deux', 'email': 'karim@garage.test', 'role': 'bureau', 'base': BASE})
    check('an email that already has an account is refused', 'déjà un compte' in (dup.get('message') or ''), dup)
    ltok = token('lina@garage.test', pw['lina'])
    check('only the owner can invite', fn(ltok, 'members', {'action': 'invite', 'name': 'X', 'email': 'x@garage.test', 'role': 'bureau', 'base': BASE}).get('_status') == 403)
    check('no account left half-made by refused invitations', psql("select count(*) from auth.users where email in ('x@garage.test')") == '0' and psql("select count(*) from public.members m join auth.users u on u.id = m.user_id where u.email = 'karim@garage.test'") == '1')
    check('an invited person cannot sign in before choosing a password', '_status' in (http('POST', API + '/auth/v1/token?grant_type=password', {'email': 'lea@garage.test', 'password': 'Lea-Garage-26'}) or {}))
    # ---------- 4. guide « Mettre l'app sur ton téléphone » (owner, computer) ----------
    op.evaluate("location.hash = 'accueil'"); op.wait_for_timeout(600)
    item = op.locator('#guide li', has_text='Mettre l\'app sur ton téléphone')
    check('guide: step « Mettre l\'app sur ton téléphone »', item.count() == 1 and item.get_attribute('class') == '' and 'On t\'explique comment' in item.inner_text())
    item.locator('button').click(); op.wait_for_timeout(600)
    check('computer: nothing to install here, a code to scan with the phone + the address', 'rien à installer' in txt(op, '.inst') and op.locator('#inst-qr svg').count() == 1 and op.is_visible('#inst-qr') and '127.0.0.1:8088/' in txt(op, '.inst-url'))
    check('both phones explained (iPhone, Android)', op.locator('.inst .inst-b').count() == 2 and 'Android' in txt(op, '.inst') and '⋮' in txt(op, '.inst'))
    op.click('[data-act="app-done"]'); op.wait_for_timeout(600)
    check('« C\'est fait » → the guide step is checked', op.locator('#guide li.ok', has_text='Mettre l\'app sur ton téléphone').count() == 1 or op.locator('#guide').count() == 0)
    oc.close()
    # ---------- 5. mechanics: a small card until the app is on the phone ----------
    sc = mk(b, phone=True); sp = page(sc, 'saleh'); login(sp, 'saleh@garage.test', pw['saleh']); sp.wait_for_timeout(800)
    check('mechanic phone (not installed): card « Mets l\'app sur ton écran d\'accueil »', sp.locator('#inst-card').count() == 1)
    sp.click('#inst-card [data-act="inst-later"]'); sp.wait_for_timeout(300); sp.reload(); sp.wait_for_timeout(1500)
    check('« Plus tard » hides it (stays hidden)', sp.locator('#inst-card').count() == 0)
    sp.click('.tab[data-t="plus"]'); sp.wait_for_timeout(400)
    check('Plus: « Mettre l\'app sur l\'écran d\'accueil » is always there', sp.locator('.ph-row[data-act="app-install"]').count() == 1)
    sc.close()
    ac = mk(b, ua=ANDROID); ap = page(ac, 'ali'); login(ap, 'ali@garage.test', pw['ali']); ap.wait_for_timeout(800)
    ap.click('#inst-card [data-act="app-install"]'); ap.wait_for_timeout(400)
    check('Android phone: Android steps first', ap.locator('.inst .inst-b').first.get_attribute('data-p') == 'android')
    ac.close()
    sc2 = mk(b, phone=True, standalone=True); sp2 = page(sc2, 'saleh-app'); login(sp2, 'saleh@garage.test', pw['saleh']); sp2.wait_for_timeout(1500)
    suid = psql("select id from auth.users where email='saleh@garage.test'")
    check('opened from the home-screen icon: no card, and it is remembered', sp2.locator('#inst-card').count() == 0 and (doc('data/users/%s/app' % suid) or {}).get('how') == 'auto')
    sc2.close()
    b.close()
check('no page errors', not ERRS, ERRS[:5])
summary()
